import express from "express";
import path from "path";
import dotenv from "dotenv";
import nodemailer from "nodemailer";
import { createServer as createViteServer } from "vite";

dotenv.config();

async function startServer() {
  const app = express();
  const PORT = 3000;

  // Use JSON parsing middleware
  app.use(express.json());

  // API Endpoint to handle contact requests
  app.post("/api/contact", async (req, res) => {
    const { name, phone, treatment, message } = req.body;

    if (!name || !phone) {
      return res.status(400).json({ 
        success: false, 
        message: "Numele și numărul de telefon sunt obligatorii." 
      });
    }

    console.log(`[Contact Form Submis] Nume: ${name}, Telefon: ${phone}, Serviciu: ${treatment}`);

    const smtpHost = process.env.SMTP_HOST;
    const smtpPort = process.env.SMTP_PORT;
    const smtpUser = process.env.SMTP_USER;
    const smtpPass = process.env.SMTP_PASS;
    const receiverEmail = process.env.CONTACT_RECEIVER_EMAIL;

    // Check if SMTP is fully configured
    const isSmtpConfigured = !!(smtpHost && smtpPort && smtpUser && smtpPass && receiverEmail);

    if (!isSmtpConfigured) {
      console.warn("⚠️ [SMTP Warning] Variabilele de mediu SMTP nu sunt complet configurate. Solicitarea a fost salvată în consolă.");
      return res.status(200).json({
        success: true,
        smtpConfigured: false,
        message: "Mesajul a fost salvat ca simulare! Pentru trimiterea reală prin email, te rugăm să adaugi credențialele tale de SMTP în zona de Secrets / `.env`."
      });
    }

    try {
      // Build the nodemailer transporter
      const transporter = nodemailer.createTransport({
        host: smtpHost,
        port: parseInt(smtpPort || "587", 10),
        secure: smtpPort === "465", // true for port 465, false for other ports
        auth: {
          user: smtpUser,
          pass: smtpPass,
        },
      });

      // Simple map for Romanian translation of services
      const servicesMap: { [key: string]: string } = {
        urgenta: "🔴 Urgență stomatologică rapidă",
        consultatie: "📅 Consultație & Plan de tratament",
        igienizare: "✨ Detartraj și igienizare",
        "tratament-canal": "🦷 Tratament de canal / Extirpare",
        "coroane-proteze": "👑 Coroane / Proteze dentare",
        implant: "🔋 Implant stomatologic"
      };

      const selectedService = servicesMap[treatment] || treatment;

      // Construct a modern HTML template for notifications
      const htmlContent = `
        <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; border: 1px solid #e2e8f0; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0,0,0,0.1);">
          <div style="background-color: #0f172a; padding: 24px; text-align: center; color: #ffffff;">
            <h2 style="margin: 0; font-size: 20px; font-weight: 800; letter-spacing: -0.5px;">Cabinet Stomatologic Ștefan cel Mare</h2>
            <p style="margin: 4px 0 0 0; font-size: 13px; color: #38bdf8; font-weight: 700; text-transform: uppercase; letter-spacing: 1px;">Solicitare Nouă de Programare</p>
          </div>
          <div style="padding: 24px; background-color: #ffffff; color: #334155; line-height: 1.6;">
            <p style="margin-top: 0; font-size: 15px;">Bună ziua,</p>
            <p style="font-size: 14px;">Ați primit o nouă solicitare de programare/contact de pe site-ul oficial:</p>
            
            <table style="width: 100%; border-collapse: collapse; margin: 20px 0;">
              <tr>
                <td style="padding: 10px; border-bottom: 1px solid #f1f5f9; font-weight: bold; width: 35%; color: #64748b;">Nume Complet</td>
                <td style="padding: 10px; border-bottom: 1px solid #f1f5f9; font-weight: bold; color: #0f172a;">${name}</td>
              </tr>
              <tr>
                <td style="padding: 10px; border-bottom: 1px solid #f1f5f9; font-weight: bold; color: #64748b;">Număr Telefon</td>
                <td style="padding: 10px; border-bottom: 1px solid #f1f5f9; font-weight: bold; color: #0284c7;">
                  <a href="tel:${phone}" style="color: #0284c7; text-decoration: none;">${phone}</a>
                </td>
              </tr>
              <tr>
                <td style="padding: 10px; border-bottom: 1px solid #f1f5f9; font-weight: bold; color: #64748b;">Serviciu Solicitat</td>
                <td style="padding: 10px; border-bottom: 1px solid #f1f5f9; font-weight: bold; color: #0f172a;">${selectedService}</td>
              </tr>
              <tr>
                <td style="padding: 10px; border-bottom: 1px solid #f1f5f9; font-weight: bold; color: #64748b; vertical-align: top;">Mesaj / Simptome</td>
                <td style="padding: 10px; border-bottom: 1px solid #f1f5f9; color: #334155; font-style: italic;">"${message || 'Fără detalii suplimentare'}"</td>
              </tr>
            </table>

            <div style="background-color: #f8fafc; padding: 12px 16px; border-radius: 8px; border: 1px solid #e2e8f0; font-size: 12px; color: #64748b; text-align: center;">
              Vă rugăm să contactați pacientul la numărul indicat în cel mai scurt timp posibil.
            </div>
          </div>
          <div style="background-color: #f1f5f9; padding: 12px 24px; text-align: center; font-size: 11px; color: #94a3b8; border-top: 1px solid #e2e8f0;">
            Trimis automat din sistemul site-ului cabinetului stomatologic Ștefan cel Mare.
          </div>
        </div>
      `;

      await transporter.sendMail({
        from: `"${name} - Solicitare Clinică" <${smtpUser}>`,
        to: receiverEmail,
        replyTo: smtpUser,
        subject: `[Programare] ${name} - ${selectedService}`,
        html: htmlContent,
      });

      console.log(`✅ [Email Succeeded] Email trimis de la ${name} către ${receiverEmail}`);
      return res.status(200).json({ success: true, smtpConfigured: true });

    } catch (error: any) {
      console.error("❌ [Email Error] Eroare la trimiterea emailului prin SMTP:", error);
      return res.status(500).json({ 
        success: false, 
        message: "A apărut o eroare la conectarea cu serverul de email SMTP. Te rugăm să verifici corectitudinea datelor introduse.",
        error: error.message
      });
    }
  });

  // Vite middleware setup
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`[Fullstack Server] Server running on http://localhost:${PORT}`);
  });
}

startServer();
